"use client";
import { useEffect, useState } from "react";
import { Stat } from "@/components/stat";

type Blob = { count: number; zero_days: { cve?: string }[] };

// Live zero-day count from /zeroday.json (generated by tools/zeroday-ledger.py export).
// Renders NOTHING until the ledger has at least one novel, verified, disclosed finding —
// the site never advertises "0 zero-days". Every entry shown passed the novelty gate.
export function ZeroDayStat() {
  const [blob, setBlob] = useState<Blob | null>(null);

  useEffect(() => {
    fetch("/zeroday.json")
      .then((r) => (r.ok ? r.json() : null))
      .then((d: Blob | null) => setBlob(d))
      .catch(() => setBlob(null));
  }, []);

  if (!blob || !blob.count) return null;
  const cves = blob.zero_days.filter((z) => z.cve).length;
  const sub = cves
    ? `${cves} with a CVE assigned. Every one novel, verified, disclosed.`
    : "Previously unknown, verified on live targets — never a scanner n-day.";

  return <Stat value={blob.count} label="Zero-days found" sub={sub} tone="green" />;
}
